namespace StoopidChess.Core;

/// <summary>
/// Zobrist hash keys for positions. See https://www.chessprogramming.org/Zobrist_Hashing
/// The keys are generated by fixed-seed 64-bit linear congruential generators, so they are identical
/// on every run and every platform, which keeps searches reproducible.
/// </summary>
public static class Zobrist
{
    public static readonly ZobristKeys Primary = new(
        seed: 0x72B32F6D517CD491, multiplier: 0x27BB2EE687B0B0FD, increment: 0x00000000B504F32D);
}

/// <summary>
/// One complete set of Zobrist keys.
/// </summary>
public sealed class ZobristKeys
{
    private const int PieceTypes = 7;
    private const int Colours = 3;
    private const int BoardSize = 128;

    private readonly ulong[] pieces = new ulong[Colours * PieceTypes * BoardSize];
    private readonly ulong[] castling = new ulong[16];
    private readonly ulong[] enPassant = new ulong[BoardSize];

    internal ZobristKeys(ulong seed, ulong multiplier, ulong increment)
    {
        ulong state = seed;
        ulong Next()
        {
            state = unchecked((multiplier * state) + increment);
            return state;
        }

        SideToMove = Next();
        for (int i = 0; i < pieces.Length; i++)
        {
            pieces[i] = Next();
        }
        // No castling rights contributes nothing, so a bare board with no rights has key zero.
        castling[0] = 0;
        for (int i = 1; i < castling.Length; i++)
        {
            castling[i] = Next();
        }
        for (int i = 0; i < enPassant.Length; i++)
        {
            enPassant[i] = Next();
        }
    }

    /// <summary>
    /// XORed into the key when it is black's turn to move.
    /// </summary>
    public ulong SideToMove { get; }

    public ulong Piece(Piece piece, int square)
    {
        return pieces[((((int)piece.Colour * PieceTypes) + (int)piece.Type) * BoardSize) + square];
    }

    public ulong Castling(CastlingRights rights) => castling[(int)rights];

    /// <summary>
    /// The key for an en passant square; zero for <see cref="Squares.None"/>.
    /// </summary>
    public ulong EnPassant(int square) => square == Squares.None ? 0 : enPassant[square];
}
